style:
main.bodymap{
    --paper: #F3EFE6;
    --ink: #1E1B16;
    --dust: #6B6257;
    --hair: #D9D2C4;
    --cinnabar: #B5402A;
    --cinnabar-wash: #F3DDD3;
    --plate: #FBF9F4;
    --f-display: "Fraunces", "Iowan Old Style", Georgia, serif;
    --f-body: "Source Serif 4", Georgia, serif;
    --f-mono: "IBM Plex Mono", ui-monospace, Menlo, monospace;
    --f-zh: "Noto Serif SC", "Songti SC", "SimSun", serif;
    --f-dev: "Noto Serif Devanagari", "Devanagari MT", serif;
    --measure: 62ch;
  }
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --paper: #15130F; --ink: #EDE7DA; --dust: #A39A8C; --hair: #322D26;
      --cinnabar: #E8735A; --cinnabar-wash: #3A201A; --plate: #1D1A15;
    }
  }main.bodymap[data-theme="dark"]{
    --paper: #15130F; --ink: #EDE7DA; --dust: #A39A8C; --hair: #322D26;
    --cinnabar: #E8735A; --cinnabar-wash: #3A201A; --plate: #1D1A15;
  }main.bodymap *, main.bodymap *::before, main.bodymap *::after{ box-sizing: border-box; }main.bodymap{
    margin: 0; background: var(--paper); color: var(--ink);
    font-family: var(--f-body); font-size: 17px; line-height: 1.6;
    padding-inline: clamp(16px, 5vw, 64px); padding-block: 0 80px;
  }main.bodymap .wrap{ max-width: 1120px; margin-inline: auto; }main.bodymap a{ color: inherit; text-decoration-color: var(--hair); text-underline-offset: .18em; }main.bodymap a:hover{ text-decoration-color: var(--cinnabar); }main.bodymap a:focus-visible{ outline: 2px solid var(--cinnabar); outline-offset: 3px; }main.bodymap [lang="zh"]{ font-family: var(--f-zh); font-style: normal; }main.bodymap [lang="sa"], main.bodymap [lang="hi"]{ font-family: var(--f-dev); font-style: normal; }main.bodymap [lang="ar"]{ font-family: "Noto Naskh Arabic", "Geeza Pro", serif; font-style: normal; direction: rtl; text-align: right; }main.bodymap .orig[lang="ar"]{ font-size: 1.25rem; line-height: 1.9; }main.bodymap .orig[lang="el"]{ font-size: 1.05rem; }main.bodymap .sec-head h2 [lang="el"], main.bodymap .sec-head h2 [lang="la"]{ font-size: .72em; color: var(--dust); margin-left: .4em; font-weight: 400; font-style: italic; }main.bodymap img{ max-width: 100%; height: auto; }
  /* woodcuts print black on white; in the dark theme invert them onto the paper */
  @media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) img.wc { filter: invert(1) brightness(.92); } }main.bodymap[data-theme="dark"] img.wc{ filter: invert(1) brightness(.92); }main.bodymap /* ---- masthead ---- */
  .masthead{ padding-block: clamp(40px, 8vw, 88px) 24px; display: grid; gap: 20px; }main.bodymap .kicker{ font-family: var(--f-mono); font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--dust); margin: 0; }main.bodymap h1{ font-family: var(--f-display); font-weight: 300; font-size: clamp(2.7rem, 7vw, 5.2rem); line-height: .98; letter-spacing: -.02em; margin: 0; max-width: 14ch; text-wrap: balance; font-variation-settings: "opsz" 144; }main.bodymap .dek{ font-size: clamp(1.08rem, 1.6vw, 1.22rem); max-width: var(--measure); margin: 0; text-wrap: pretty; }main.bodymap .legend{ font-family: var(--f-mono); font-size: 12px; color: var(--dust); max-width: 80ch; margin: 8px 0 0; line-height: 1.5; }main.bodymap .legend b{ font-weight: 500; color: var(--ink); }main.bodymap /* ---- section heads ---- */
  .sec{ margin-top: 72px; }main.bodymap .sec-head{ display: flex; align-items: baseline; justify-content: space-between; gap: 16px; flex-wrap: wrap; border-bottom: 1px solid var(--ink); padding-bottom: 8px; margin-bottom: 8px; }main.bodymap .sec-head h2{ font-family: var(--f-display); font-weight: 300; font-size: clamp(2rem, 4.4vw, 3rem); line-height: 1; margin: 0; letter-spacing: -.01em; }main.bodymap .sec-head h2 [lang="zh"], main.bodymap .sec-head h2 [lang="sa"]{ font-size: .72em; color: var(--dust); margin-left: .4em; font-weight: 400; }main.bodymap .sec-head .src{ font-family: var(--f-mono); font-size: 12px; color: var(--dust); max-width: 60ch; }main.bodymap .lede{ max-width: var(--measure); margin: 14px 0 0; text-wrap: pretty; }main.bodymap /* ---- the year: 24 terms ---- */
  .year{ list-style: none; margin: 28px 0 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 22px 16px; }main.bodymap .term{ display: grid; gap: 6px; min-width: 0; }main.bodymap .term-link{ display: grid; gap: 4px; text-decoration: none; }main.bodymap .term-link img{ width: 100%; aspect-ratio: 1; object-fit: contain; background: var(--plate); border: 1px solid var(--hair); padding: 6px; }main.bodymap .term-link:hover img{ border-color: var(--cinnabar); }main.bodymap .t-zh{ font-family: var(--f-zh); font-size: 1.3rem; line-height: 1.1; margin-top: 4px; }main.bodymap .t-en{ font-size: .92rem; line-height: 1.25; }main.bodymap .t-n{ font-family: var(--f-mono); font-size: 12px; color: var(--cinnabar); }main.bodymap .term details{ font-size: .95rem; }main.bodymap .term summary{ font-family: var(--f-mono); font-size: 11.5px; color: var(--dust); cursor: pointer; letter-spacing: .04em; }main.bodymap .term summary:hover{ color: var(--ink); }main.bodymap .term .zh{ font-size: 1.02rem; line-height: 1.7; margin: 8px 0 4px; }main.bodymap .term .en{ margin: 0 0 4px; line-height: 1.5; }main.bodymap .term .src{ font-family: var(--f-mono); font-size: 11px; color: var(--dust); margin: 0; }main.bodymap /* ---- methods ---- */
  .methods{ display: grid; gap: 0; margin-top: 8px; }main.bodymap .method{ display: grid; grid-template-columns: 180px 1fr; gap: 12px clamp(20px, 3vw, 40px); padding-block: 28px; border-bottom: 1px solid var(--hair); }main.bodymap .m-img{ width: 180px; aspect-ratio: 1; object-fit: contain; background: var(--plate); border: 1px solid var(--hair); padding: 8px; }main.bodymap .m-text{ display: grid; gap: 10px; align-content: start; min-width: 0; }main.bodymap .m-count{ margin: 0; }main.bodymap .num{ font-family: var(--f-display); font-weight: 300; font-size: 2.4rem; line-height: 1; color: var(--cinnabar); font-variant-numeric: lining-nums tabular-nums; }main.bodymap .name{ margin: 0; font-family: var(--f-display); font-weight: 400; font-size: clamp(1.5rem, 2.4vw, 1.9rem); line-height: 1.15; text-wrap: balance; }main.bodymap .name .tr{ font-style: italic; font-weight: 300; }main.bodymap .name [lang="zh"]{ font-size: 1.1em; }main.bodymap .zh{ font-size: 1.12rem; line-height: 1.85; margin: 0; max-width: 40em; }main.bodymap .en{ margin: 0; max-width: var(--measure); font-size: 1.06rem; line-height: 1.55; text-wrap: pretty; }main.bodymap .note{ margin: 0; color: var(--dust); font-style: italic; font-size: .95rem; max-width: var(--measure); }main.bodymap .src{ margin: 0; font-family: var(--f-mono); font-size: 11.5px; color: var(--dust); }main.bodymap /* ---- parallel text (Sanskrit / Tibetan / Chinese prose) ---- */
  .entry{ display: grid; grid-template-columns: minmax(6rem, 8.5rem) 1fr; gap: 10px clamp(20px, 3vw, 40px); padding-block: 28px; border-bottom: 1px solid var(--hair); }main.bodymap .tally{ display: grid; align-content: start; gap: 4px; }main.bodymap .tally .num{ font-size: clamp(2.2rem, 4.6vw, 3.2rem); }main.bodymap .tally .unit{ font-family: var(--f-mono); font-size: 12px; color: var(--dust); line-height: 1.35; }main.bodymap .tally .none{ font-family: var(--f-mono); font-size: 12px; color: var(--dust); padding-top: 8px; }main.bodymap .text{ display: grid; gap: 10px; min-width: 0; }main.bodymap .meta{ margin: 0; font-family: var(--f-mono); font-size: 12px; color: var(--dust); display: flex; flex-wrap: wrap; gap: 2px 14px; }main.bodymap .orig{ margin: 0; max-width: 46em; font-size: 1.15rem; line-height: 1.9; }main.bodymap .orig[lang="sa"], main.bodymap .orig[lang="hi"]{ font-size: 1.2rem; }main.bodymap .verse{ margin: 0; font-family: var(--f-mono); font-size: 11px; color: var(--dust); }main.bodymap .pair{ display: grid; grid-template-columns: 1fr; gap: 12px; }
  @media (min-width: 900px) { .pair.wide { grid-template-columns: 1fr 1fr; gap: 28px; align-items: start; } }main.bodymap .foot{ display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px 20px; align-items: baseline; }main.bodymap /* ---- plates ---- */
  .plates{ display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 26px 20px; margin-top: 26px; }main.bodymap .plate figure{ margin: 0; }main.bodymap .plate img{ width: 100%; height: auto; display: block; border-radius: 2px; background: #efe9dd; }main.bodymap .plate figcaption{ margin-top: 8px; display: flex; flex-direction: column; gap: 2px; }main.bodymap .plate .pn{ font-family: var(--f-display); font-weight: 400; font-size: 1.05rem; line-height: 1.2; }main.bodymap .plate .psa{ font-family: var(--f-dev); font-size: .95rem; color: var(--dust); }main.bodymap .plate a{ color: var(--cinnabar); text-decoration: none; font-family: var(--f-mono); font-size: 11px; }main.bodymap .wide{ margin-top: 26px; }main.bodymap .wide img{ width: 100%; height: auto; display: block; border-radius: 2px; }main.bodymap .wide figcaption{ margin-top: 8px; font-family: var(--f-mono); font-size: 12px; color: var(--dust); max-width: 70ch; line-height: 1.5; }main.bodymap .read{ font-family: var(--f-mono); font-size: 12.5px; color: var(--cinnabar); text-decoration: none; white-space: nowrap; }main.bodymap .read:hover{ text-decoration: underline; }main.bodymap /* ---- colophon ---- */
  .colophon{ margin-top: 88px; padding-top: 28px; border-top: 1px solid var(--ink); display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 28px clamp(24px, 5vw, 64px); }main.bodymap .colophon h2{ font-family: var(--f-mono); font-size: 12px; font-weight: 500; letter-spacing: .12em; text-transform: uppercase; color: var(--dust); margin: 0 0 10px; }main.bodymap .colophon p{ margin: 0; font-size: .98rem; max-width: 60ch; }main.bodymap .colophon p + p{ margin-top: 10px; }

  @media (max-width: 640px) {
    .method { grid-template-columns: 1fr; }main.bodymap .m-img{ width: 140px; }main.bodymap .entry{ grid-template-columns: 1fr; }main.bodymap .tally{ grid-auto-flow: column; justify-content: start; align-items: baseline; gap: 10px; }main.bodymap .tally .none{ padding-top: 0; }
  }
  @media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
